import Component from "@glimmer/component";
import { service } from "@ember/service";
import { trustHTML } from "@ember/template";
import { userPath } from "discourse/lib/url";
import DUserAvatarFlair from "discourse/ui-kit/d-user-avatar-flair";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import { renderAvatar } from "discourse/ui-kit/helpers/d-user-avatar";

export default class ChatUserAvatar extends Component {
  @service chatStateManager;
  @service chat;

  get avatar() {
    return trustHTML(
      renderAvatar(this.args.user, { imageSize: this.avatarSize })
    );
  }

  get interactive() {
    return this.args.interactive ?? true;
  }

  get avatarSize() {
    return this.args.avatarSize || "tiny";
  }

  get showPresence() {
    return this.args.showPresence ?? true;
  }

  get isOnline() {
    const users = (this.args.chat || this.chat).presenceChannel?.users;

    return (
      this.showPresence &&
      !!users?.find(
        ({ id, username }) =>
          this.args.user?.id === id || this.args.user?.username === username
      )
    );
  }

  get userPath() {
    return userPath(this.args.user.username);
  }

  get ariaHidden() {
    return this.args.ariaHidden ?? false;
  }

  get isFullPageActive() {
    return this.chatStateManager.isFullPageActive ? "true" : "false";
  }

  <template>
    <div
      class={{dConcatClass "chat-user-avatar" (if this.isOnline "is-online")}}
      data-username={{@user.username}}
    >
      {{#if this.interactive}}
        <a
          aria-hidden={{if this.ariaHidden "true"}}
          class="chat-user-avatar__container"
          data-user-card={{@user.username}}
          href={{this.userPath}}
          tabindex={{if this.ariaHidden "-1"}}
        >
          {{this.avatar}}
          <DUserAvatarFlair @user={{@user}} />
        </a>
      {{else}}
        <span
          aria-hidden={{if this.ariaHidden "true"}}
          class="chat-user-avatar__container"
        >
          {{this.avatar}}
          <DUserAvatarFlair @user={{@user}} />
        </span>
      {{/if}}
    </div>
  </template>
}
import Component from "@glimmer/component";
import { trustHTML } from "@ember/template";
import dEmoji from "discourse/ui-kit/helpers/d-emoji";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import ChatUserAvatar from "discourse/plugins/chat/discourse/components/chat-user-avatar";

export default class ChatChannelIcon extends Component {
  get firstUser() {
    return this.args.channel.chatable.users[0];
  }

  get groupDirectMessage() {
    return (
      this.args.channel.isDirectMessageChannel &&
      this.args.channel.chatable.group
    );
  }

  get groupIsDuoOnly() {
    return (
      this.args.channel.chatable.group &&
      // User array does not include the current user
      this.args.channel.chatable.users.length === 1
    );
  }

  get channelColorStyle() {
    return trustHTML(`color: #${this.args.channel.chatable.color}`);
  }

  get isThreadsList() {
    return this.args.thread ?? false;
  }

  get categoryChannelIcon() {
    return this.channelEmoji || dIcon("d-chat");
  }

  get channelEmoji() {
    const { emoji } = this.args.channel;
    return emoji && dEmoji(emoji);
  }

  <template>
    {{#if @channel.isDirectMessageChannel}}
      {{#if this.groupDirectMessage}}
        {{#if this.channelEmoji}}
          <div class="chat-channel-icon --emoji">
            {{this.channelEmoji}}
          </div>
        {{else if this.groupIsDuoOnly}}
          <div class="chat-channel-icon --avatar">
            <ChatUserAvatar @interactive={{false}} @user={{this.firstUser}} />
          </div>
        {{else}}
          <div class="chat-channel-icon --users-count">
            {{@channel.membershipsCount}}
          </div>
        {{/if}}
      {{else}}
        <div class="chat-channel-icon --avatar">
          <ChatUserAvatar @interactive={{false}} @user={{this.firstUser}} />
        </div>
      {{/if}}
    {{else if @channel.isCategoryChannel}}
      <div class="chat-channel-icon --icon" style={{this.channelColorStyle}}>
        {{this.categoryChannelIcon}}
        {{#if @channel.chatable.read_restricted}}
          {{dIcon "lock" class="chat-channel-icon__restricted-category-icon"}}
        {{/if}}
      </div>
    {{else if this.isThreadsList}}
      <div class="chat-channel-icon --avatar">
        <ChatUserAvatar
          @interactive={{true}}
          @showPresence={{false}}
          @user={{@thread.preview.lastReplyUser}}
        />
        <div class="avatar-flair --threads">
          {{dIcon "discourse-threads"}}
        </div>
      </div>
    {{/if}}
  </template>
}
import Component from "@glimmer/component";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";

const MAX_UNREAD_COUNT = 99;

export default class ChatChannelUnreadIndicator extends Component {
  get showUnreadIndicator() {
    return (
      this.args.channel.tracking.unreadCount +
        this.args.channel.tracking.mentionCount +
        this.args.channel.unreadThreadsCountSinceLastViewed >
      0
    );
  }

  get publicUrgentCount() {
    return (
      this.args.channel.tracking.mentionCount +
      this.args.channel.tracking.watchedThreadsUnreadCount
    );
  }

  get directUrgentCount() {
    return (
      this.args.channel.tracking.unreadCount +
      this.args.channel.tracking.mentionCount +
      this.args.channel.tracking.watchedThreadsUnreadCount
    );
  }

  get urgentCount() {
    return this.args.channel.isDirectMessageChannel
      ? this.directUrgentCount
      : this.publicUrgentCount;
  }

  get isUrgent() {
    return this.urgentCount > 0;
  }

  get urgentBadgeCount() {
    const totalCount = this.urgentCount;
    return totalCount > MAX_UNREAD_COUNT ? `${MAX_UNREAD_COUNT}+` : totalCount;
  }

  <template>
    {{#if this.showUnreadIndicator}}
      <div
        class={{dConcatClass
          "c-unread-indicator chat-channel-unread-indicator"
          (if this.isUrgent "-urgent" "d-new-indicator")
        }}
      >
        <div
          class="c-unread-indicator__number chat-channel-unread-indicator__number"
        >
          {{#if this.isUrgent}}{{this.urgentBadgeCount}}{{else}}&nbsp;{{/if}}
        </div>
      </div>
    {{/if}}
  </template>
}
import Component from "@glimmer/component";
import { get } from "@ember/helper";
import { service } from "@ember/service";
import { trustHTML } from "@ember/template";
import PluginOutlet from "discourse/components/plugin-outlet";
import lazyHash from "discourse/helpers/lazy-hash";
import DUserStatusMessage from "discourse/ui-kit/d-user-status-message";
import dReplaceEmoji from "discourse/ui-kit/helpers/d-replace-emoji";
import ChatChannelUnreadIndicator from "../chat-channel-unread-indicator.gjs";

export default class ChatChannelName extends Component {
  @service currentUser;
  @service siteSettings;

  get unreadIndicator() {
    return this.args.unreadIndicator ?? false;
  }

  get users() {
    return this.args.channel.chatable.users;
  }

  get prefersName() {
    return (
      this.siteSettings.enable_names &&
      this.siteSettings.display_name_on_posts &&
      !this.siteSettings.prioritize_username_in_ux
    );
  }

  get directMessageTitle() {
    if (this.users.length === 0) {
      return this.prefersName
        ? this.currentUser.name || this.currentUser.username
        : this.currentUser.username;
    }
    return this.prefersName
      ? this.users.map((user) => user.name || user.username).join(", ")
      : this.users.map((user) => user.username).join(", ");
  }

  get channelColorStyle() {
    return trustHTML(`color: #${this.args.channel.chatable.color}`);
  }

  get showUserStatus() {
    if (!this.args.channel.isDirectMessageChannel) {
      return false;
    }
    return !!(this.users.length === 1 && this.users[0].status);
  }

  get channelTitle() {
    if (this.args.channel.isDirectMessageChannel) {
      return this.args.channel.displayTitle ?? this.directMessageTitle;
    }

    return this.args.channel.displayTitle;
  }

  get showPluginOutlet() {
    return (
      this.args.channel.isDirectMessageChannel &&
      !this.args.channel.chatable.group
    );
  }

  <template>
    <div class="chat-channel-name">
      <div class="chat-channel-name__label">
        {{dReplaceEmoji this.channelTitle}}

        {{#if this.showUserStatus}}
          <DUserStatusMessage
            class="chat-channel__user-status-message"
            @showDescription={{if this.site.mobileView "true"}}
            @status={{get this.users "0.status"}}
          />
        {{/if}}

        <PluginOutlet
          @name="after-chat-channel-username"
          @outletArgs={{if this.showPluginOutlet (lazyHash user=@user)}}
        />

        {{#if (has-block)}}
          {{yield}}
        {{/if}}
      </div>

      {{#if this.unreadIndicator}}
        <ChatChannelUnreadIndicator @channel={{@channel}} />
      {{/if}}
    </div>
  </template>
}
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import ChannelIcon from "discourse/plugins/chat/discourse/components/channel-icon";
import ChannelName from "discourse/plugins/chat/discourse/components/channel-name";

const ChatChannelTitle = <template>
  <div
    class={{dConcatClass
      "chat-channel-title"
      (if @channel.isDirectMessageChannel "is-dm" "is-category")
    }}
  >
    <ChannelIcon @channel={{@channel}} />
    <ChannelName @channel={{@channel}} />

    {{#if @isUnread}}
      <div
        class="unread-indicator d-new-indicator {{if @isUrgent '-urgent'}}"
      ></div>
    {{/if}}

    {{#if (has-block)}}
      {{yield}}
    {{/if}}
  </div>
</template>;

export default ChatChannelTitle;
import ComboBoxSelectBoxHeaderComponent from "discourse/select-kit/components/combo-box/combo-box-header";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";
