export default class ChatChannelChooserHeader extends ComboBoxSelectBoxHeaderComponent {
  <template>
    <div class="select-kit-header-wrapper">
      {{#if this.selectedContent}}
        <ChannelTitle @channel={{this.selectedContent}} />
