export default function slugifyChannel(channel) {
  if (channel.slug) {
    return channel.slug;
  }

  if (!channel.escapedTitle && !channel.title) {
    return "-";
  }

  const slug = slugify(channel.escapedTitle || channel.title);
  const resolvedSlug = (
    slug.length
      ? slug
      : channel.title.trim().toLowerCase().replace(/\s|_+/g, "-")
  ).slice(0, 100);

  if (!resolvedSlug) {
    return "-";
  }

  return resolvedSlug;
}
